import heapq
class Solution:
    def minTime(self, n, k, m, time, mul):
        full = (1 << n) - 1
        INF = float('inf')
        dist = {}
        pq = [(0.0, 0, 0)]
        while pq:
            d, mask, st = heapq.heappop(pq)
            if d > dist.get((mask, st), INF) + 1e-9:
                continue
            if mask == full:
                return d
            rem = full & ~mask
            sub = rem
            while sub:
                if bin(sub).count('1') <= k:
                    mx = max(time[i] for i in range(n) if (sub >> i) & 1)
                    cross = mx * mul[st]
                    t2 = d + cross
                    st2 = (st + int(cross)) % m
                    nmask = mask | sub
                    if nmask == full:
                        key = (nmask, st2)
                        if t2 < dist.get(key, INF) - 1e-9:
                            dist[key] = t2
                            heapq.heappush(pq, (t2, nmask, st2))
                    else:
                        for r in range(n):
                            if (sub >> r) & 1:
                                rt = time[r] * mul[st2]
                                tot = t2 + rt
                                st3 = (st2 + int(rt)) % m
                                key = (nmask & ~(1 << r), st3)
                                if tot < dist.get(key, INF) - 1e-9:
                                    dist[key] = tot
                                    heapq.heappush(pq, (tot, key[0], st3))
                sub = (sub - 1) & rem
        return -1.0

