class Solution {
public:
    double minTime(int n, int k, int m, vector<int>& time, vector<double>& mul) {
        int full = (1 << n) - 1;
        map<pair<int,int>, double> dist;
        priority_queue<tuple<double,int,int>, vector<tuple<double,int,int>>, greater<>> pq;
        pq.push({0.0, 0, 0});
        while (!pq.empty()) {
            auto [d, mask, st] = pq.top(); pq.pop();
            auto it = dist.find({mask, st});
            if (it != dist.end() && d > it->second + 1e-9) continue;
            if (mask == full) return d;
            int rem = full & ~mask;
            for (int sub = rem; sub; sub = (sub - 1) & rem) {
                if (__builtin_popcount(sub) > k) continue;
                double mx = 0;
                for (int i = 0; i < n; i++) if (sub >> i & 1) mx = max(mx, (double)time[i]);
                double cross = mx * mul[st];
                double t2 = d + cross;
                int st2 = (st + (int)cross) % m;
                int nmask = mask | sub;
                if (nmask == full) {
                    auto key = make_pair(nmask, st2);
                    if (!dist.count(key) || t2 < dist[key] - 1e-9) { dist[key] = t2; pq.push({t2, nmask, st2}); }
                } else {
                    for (int r = 0; r < n; r++) if (sub >> r & 1) {
                        double rt = time[r] * mul[st2];
                        double tot = t2 + rt;
                        int st3 = (st2 + (int)rt) % m;
                        auto key = make_pair(nmask & ~(1 << r), st3);
                        if (!dist.count(key) || tot < dist[key] - 1e-9) { dist[key] = tot; pq.push({tot, key.first, st3}); }
                    }
                }
            }
        }
        return -1.0;
    }
};

