class Solution {
    public double minTime(int n, int k, int m, int[] time, double[] mul) {
        int full = (1 << n) - 1;
        Map<Long, Double> dist = new HashMap<>();
        PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(a[0], b[0]));
        pq.offer(new double[]{0.0, 0, 0});
        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            double d = cur[0]; int mask = (int) cur[1], st = (int) cur[2];
            Double known = dist.get(((long) mask << 3) | st);
            if (known != null && d > known + 1e-9) continue;
            if (mask == full) return d;
            int rem = full & ~mask;
            for (int sub = rem; sub > 0; sub = (sub - 1) & rem) {
                if (Integer.bitCount(sub) > k) continue;
                double mx = 0;
                for (int i = 0; i < n; i++) if ((sub >> i & 1) == 1) mx = Math.max(mx, time[i]);
                double cross = mx * mul[st];
                double t2 = d + cross;
                int st2 = (st + (int) cross) % m;
                int nmask = mask | sub;
                if (nmask == full) {
                    long key = ((long) nmask << 3) | st2;
                    Double kd = dist.get(key);
                    if (kd == null || t2 < kd - 1e-9) { dist.put(key, t2); pq.offer(new double[]{t2, nmask, st2}); }
                } else {
                    for (int r = 0; r < n; r++) if ((sub >> r & 1) == 1) {
                        double rt = time[r] * mul[st2];
                        double tot = t2 + rt;
                        int st3 = (st2 + (int) rt) % m;
                        long key = ((long) (nmask & ~(1 << r)) << 3) | st3;
                        Double kd = dist.get(key);
                        if (kd == null || tot < kd - 1e-9) { dist.put(key, tot); pq.offer(new double[]{tot, nmask & ~(1 << r), st3}); }
                    }
                }
            }
        }
        return -1.0;
    }
}

