var minTime = function(n, k, m, time, mul) {
    const full = (1 << n) - 1;
    const dist = new Map();
    const pq = [[0.0, 0, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, mask, st] = pq.shift();
        const kk = mask * 8 + st;
        if (dist.has(kk) && d > dist.get(kk) + 1e-9) continue;
        if (mask === full) return d;
        const rem = full & ~mask;
        for (let sub = rem; sub > 0; sub = (sub - 1) & rem) {
            let bits = 0;
            for (let i = 0; i < n; i++) if ((sub >> i) & 1) bits++;
            if (bits > k) continue;
            let mx = 0;
            for (let i = 0; i < n; i++) if ((sub >> i) & 1) mx = Math.max(mx, time[i]);
            const cross = mx * mul[st];
            const t2 = d + cross;
            const st2 = (st + Math.floor(cross)) % m;
            const nmask = mask | sub;
            if (nmask === full) {
                const key = nmask * 8 + st2;
                if (!dist.has(key) || t2 < dist.get(key) - 1e-9) { dist.set(key, t2); pq.push([t2, nmask, st2]); }
            } else {
                for (let r = 0; r < n; r++) if ((sub >> r) & 1) {
                    const rt = time[r] * mul[st2];
                    const tot = t2 + rt;
                    const st3 = (st2 + Math.floor(rt)) % m;
                    const key = (nmask & ~(1 << r)) * 8 + st3;
                    if (!dist.has(key) || tot < dist.get(key) - 1e-9) { dist.set(key, tot); pq.push([tot, nmask & ~(1 << r), st3]); }
                }
            }
        }
    }
    return -1.0;
};
